// locales.js — UI strings for every supported language. English is the canonical key set;
// t() falls back to English for any key a translation is missing. Technical proper nouns
// (translator/detector/model identifiers in the advanced translator modal) are intentionally
// left in English inside the markup and are not keyed here.
//
// Placeholders: {n} count, {id} gallery id, {size} formatted size, {site} site name,
// {url} link, {name} tag name, {label} category, {msg} error, {g}/{i} gallery/image counts,
// {done}/{total} progress.

